  ui_story_5082_50820201_95_dialog_content = "การฝึกนี้ใช้เวลาถึงสองวันเต็ม ในฐานะจอมทัพ คุณจะยอมให้ลูกสมุนของคุณต้องสู้รบโดยไม่มีอาหารในท้องจริงๆหรือ?",
  ui_story_5082_50820201_96_dialog_content = "ฮ่าฮ่าฮ่า ฉันเกือบลืมว่ารู้สึกยังไงเมื่อต้องต่อสู้กับคุณ",
  ui_story_5082_50820201_97_dialog_content = "แต่แม้ว่ามันจะหมายความว่าต้องหิว—",
  ui_story_5082_50820201_98_dialog_content = "(... หือ? อะไรในโลกนี้คือ...)",
  ui_story_5082_50820201_99_dialog_content = "(นี่เป็นวันที่สองของการฝึกฝนแล้ว สถานการณ์นี้... ดูไม่จะจบในเร็วๆ นี้)",
  ui_story_5082_50820201_100_dialog_content = "(ฉันเป็นคนเดียวที่พบกระสุนในวันแรก ไม่มีใครที่ฉันพบมีเสบียงเลย)",
  ui_story_5082_50820201_101_dialog_content = "(ฉันคงไม่ทำได้ในอัตรานี้...)",
  ui_story_5082_50820201_102_dialog_content = "เธอเป็นคนเอากระสุนไปใช่มั้ย?",
  ui_story_5082_50820201_103_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5082_50820201_104_dialog_content = "ยิงก่อนที่จะรู้ตัวตนของคนอื่น? นั่นไม่ใช่เรื่องดีเลยนะ",
  ui_story_5082_50820201_105_dialog_content = "คุณคือคนที่เข้ามาแอบแฝงในค่ายของฉัน คุณไม่มีสิทธิ์ได้รับความสุภาพใด ๆ",
  ui_story_5082_50820201_106_dialog_content = "ฮ่าฮ่าฮ่า! งั้นมาทำงานร่วมกันเถอะ ไรน์ฮาร์ต!",
  ui_story_5082_50820201_107_dialog_content = "นี่ควรจะเป็นการฝึกการรบจริง ทำไมฉันถึงต้องยินยอมที่จะร่วมทีมกับคนลอบเข้าแทรกแซงเช่นคุณล่ะ?",
  ui_story_5082_50820201_108_dialog_content = "เอาล่ะ สำหรับการเริ่มต้น ฉันได้ป้องกันการโจมตีของคุณเมื่อกี้โดยไม่ต้องใช้แรงมาก— และคุณไม่ได้ยับยั้งตัวเองเลยใช่ไหม?",
  ui_story_5082_50820201_109_dialog_content = "มีสวัสดิการอื่น ๆ ในการทำงานร่วมกับฉันด้วย อาหารสนามเป็นต้น",
  ui_story_5082_50820201_110_dialog_content = "ยังมีนักสู้ที่แข็งแกร่งอีกมากมายในการฝึกฝนนี้ มันเป็นเรื่องเวลาเท่านั้นก่อนที่จะมี \"วิคเตอร์\" ถูกตัดสิน",
  ui_story_5082_50820201_111_dialog_content = "ไม่มีทางปฏิเสธว่าฉันต้องการกระสุน และมีอะไรบางอย่างบอกฉันว่าคุณไม่อยากจะสู้รบในท้องที่ว่างเปล่าใช่มั้ยครับ?",
  ui_story_5082_50820201_112_dialog_content = "เชอะ...",
  ui_story_5082_50820201_113_dialog_content = "ข้อเสนอ.",
  ui_story_5082_50820201_114_dialog_content = "<color=#e8d9bb>2 วันให้หลัง</color>",
  ui_story_5082_50820201_115_dialog_content = "ฉันไม่คิดว่าจะสามารถทำลายทีมอื่นได้เร็วขนาดนี้ คุณเก่งมาก",
  ui_story_5082_50820201_116_dialog_content = "แน่นอนอยู่แล้ว",
  ui_story_5082_50820201_117_dialog_content = "ดูเหมือนว่าเราจะไม่ต้องต่อสู้อีกในวันนี้ คุณได้ใช้กระสุนของฉัน ดังนั้นให้กระทำอาหารของคุณมาและ—",
