  ui_story_5082_50820201_123_dialog_content = "ฉันไม่ได้กินมาสองวันแล้ว และการต่อสู้ครั้งนี้ทำให้ฉันเหนื่อยมาก มันกลายเป็นเรื่องยากขึ้นและยากขึ้นที่จะทนต่อไป",
  ui_story_5082_50820201_124_dialog_content = "ฉันจะต้องพักที่นี่ตลอดวันและรักษาพลังงานเล็ก ๆ ที่ฉันยังมีอยู่ เมื่อพรุ่งนี้มาถึง ฉันจะ...",
  ui_story_5082_50820201_125_dialog_content = "<color=#e8d9bb>อีกสองวันต่อมา</color>",
  ui_story_5082_50820201_126_dialog_content = "(ฉันรู้สึกหัวปั่น ๆ... และร่างกายของฉันรู้สึกหนักเหลือเกิน)",
  ui_story_5082_50820201_127_dialog_content = "(แต่การต่อสู้ยังไม่จบหรอกนะ ฉันต้องไปต่อ...)",
  ui_story_5082_50820201_128_dialog_content = "(แทนที่จะโกรธ ฉันต้องคิดถึงการเคลื่อนไหวถัดไปของฉัน—)",
