  ui_story_5082_50820201_132_dialog_content = "ท้ายที่สุด ผมเดาว่านักเรียนที่ดีที่สุดก็ไม่ได้มีค่าอะไรมากนัก!",
  ui_story_5082_50820201_133_dialog_content = "บอกฉันสิ, ตอนนี้อะไรที่ทำให้เจ็บมากกว่า? แผลของเธอหรือความหิว?",
