  ui_story_5082_50820301_7_dialog_content = "ใครจะไม่เป็นล่ะ? ถ้าเป็นจริง การเข้าร่วมกองทัพพิเศษก็แค่มีขั้นตอนเพียงไม่กี่ขั้นตอน!",
  ui_story_5082_50820301_8_dialog_content = "แต่ใครจะรู้ว่าพวกเขาโดนทดลองอะไรบ้าคลั่งไปบ้าง—",
