  ui_story_5082_50820501_35_dialog_content = "เมืองใต้ดินหลายแห่ง รวมถึงเมืองใต้ดินหมายเลข 38, 42, และ 59 ได้รับการโจมตีพร้อมกันจากอิคลิพไซท์ประเภทใหม่เมื่อเร็วๆนี้",
  ui_story_5082_50820501_36_dialog_content = "อิคลิพไซท์ใหม่เหล่านี้ไม่ได้มีพลังที่โดดเด่น แต่พวกมันสามารถทำให้สมดุลด้วยจำนวนที่มากขึ้นอย่างต่อเนื่อง สภาพการอยู่อาศัยและผลิตภัณฑ์ของเมืองใต้ดินเหล่านี้ได้รับผลกระทบอย่างรุนแรงแล้ว!",
  ui_story_5082_50820501_37_dialog_content = "คุณจะถูกแบ่งออกเป็นทีมเล็ก ๆ สามทีมและถูกส่งไปยัง Undercities ต่อไปนี้เพื่อให้การสนับสนุน",
