  ui_story_5082_50821201_20_dialog_content = "<color=#e8d9bb>เมื่อเปลวไฟป่าเริ่มกระจายไปทั่วทั้งพื้นที่อย่างรวดเร็ว เธอจึงเริ่มหัวเราะอย่างบ้าคลั่งในกลางเพลิงไหม้ที่รุนแรง</color>",
  ui_story_5082_50821201_21_dialog_content = "อ๊ะ, มันผ่านมานานแล้วตั้งแต่ฉันรู้สึกดีเหมือนนี้!",
  ui_story_5082_50821201_22_dialog_content = "ขอโทษนะ โคลอสซัส แต่หลังจากที่ฉันได้ยินว่าเธอเป็นเพื่อนกับอิคลิพไซท์ ฉันไม่มีความสงสารเธอเลยแล้ว",
  ui_story_5082_50821201_23_dialog_content = "ฉันไม่สามารถทำร้ายร่างกายของคุณได้ ดังนั้นการเผาไหม้จิตใจของคุณทั้งหมดจึงต้องเป็นทางออก! มันเจ็บใช่ไหม?!",
  ui_story_5082_50821201_24_dialog_content = "คุณ! กล้าดียังไง—!",
  ui_story_5082_50821201_25_dialog_content = "คุณไม่ใช่อะไรเลยนอกจากข้อมูลที่เหลืออยู่ในจิตสำนึกของฉัน! ฉันสามารถลบทางอยู่ของคุณได้เมื่อไหร่ก็ตามที่ฉันต้องการ!",
  ui_story_5082_50821201_26_dialog_content = "พื้นที่กำลังหายไป... สเปียร์เฮดต้องกำลังลบข้อมูล!",
  ui_story_5082_50821201_27_dialog_content = "ความคิดของคุณก็ถูกเก็บไว้ที่นี่ด้วยใช่มั้ย? คุณแน่ใจว่าสถานการณ์นี้โอเคหรือไม่?",
  ui_story_5082_50821201_28_dialog_content = "ฉันจะไม่เป็นไร ตราบใดที่มันไม่จับฉันได้",
  ui_story_5082_50821201_29_dialog_content = "หมายความว่าไง",
  ui_story_5082_50821201_30_dialog_content = "ฉันหมายถึง—",
  ui_story_5082_50821201_31_dialog_content = "รีบหนีไป!!!",
  ui_story_5082_50821201_32_dialog_content = "คุณดูมั่นใจมากเมื่อกี้! นี่จริงๆ แล้วเป็นความคิดที่ดีที่สุดที่คุณคิดขึ้นได้หรือเปล่า?!",
  ui_story_5082_50821201_33_dialog_content = "ฮ่าฮ่าฮ่าฮ่า!",
  ui_story_5082_50821201_34_dialog_content = "เมี้ยว!",
  ui_story_5082_50821201_35_dialog_content = "ฟิลิชี! ยังไงคุณถึงเล่นกับสิ่งเหล่านั้นได้ตอนที่พวกเราถูกโจมตีอยู่เลย?!",
  ui_story_5082_50821201_36_dialog_content = "ขอโทษนะ พวกมันดูเหมือนหางยาวโตเมื่อเชื่อมต่อกันแบบนั้น! ฉันไม่สามารถทนได้!",
  ui_story_5082_50821201_37_dialog_content = "ถ้าคุณอธิบายแบบนั้น มันก็เหมือนมีเหตุผล โคลอสซัสคงควบคุม \"หาง\" แต่ละอันเพื่อโจมตีเรา...",
  ui_story_5082_50821201_38_dialog_content = "แม้ว่ามันจะไม่สามารถเคลื่อนไหวร่างกาย แต่ศูนย์ควบคุมคำสั่งของมันยังคงทำงานได้พอที่จะโจมตีเราด้วยซากปรักษาของมัน!",
  ui_story_5082_50821201_39_dialog_content = "นั่นคือความคิดของฉันเลย!",
  ui_story_5082_50821201_40_dialog_content = "ฮึ! ตามที่ฉันเห็น โคลอสซัสที่สึกสึนนี้ดีแค่สำหรับการสั่นหางมาที่เราเท่านั้นเลย!",
  ui_story_5082_50821201_41_dialog_content = "<color=#e8d9bb>ตบ, ตบ, ตบ, ตบ—!</color>",
