  ui_story_5082_50821201_43_dialog_content = "ในทุกๆ ครั้งที่มา— เดี๋ยวก่อน, อย่าขยับ!",
  ui_story_5082_50821201_44_dialog_content = "<color=#e8d9bb>เสียงแตก—</color>",
  ui_story_5082_50821201_45_dialog_content = "... กระแสไฟฟ้าเหรอ?",
  ui_story_5082_50821201_46_dialog_content = "ออกไปจากหางนั้น ฟิลิชี! มีบางอย่างไม่ถูกต้องเกี่ยวกับมัน!",
  ui_story_5082_50821201_47_dialog_content = "บัซ—บัซ—",
  ui_story_5082_50821201_48_dialog_content = "กระดูกกำลังเพิ่มขึ้น! รักษาการณ์ดี ๆ ทุกคน; ยักษ์ใหญ่อาจจะโจมตีเร็ว ๆ นี้—",
  ui_story_5082_50821201_49_dialog_content = "<color=#e8d9bb>ตูม! ตูม! ตูม!</color>",
  ui_story_5082_50821201_50_dialog_content = "ฉันสามารถรับกลิ่นระเบิดที่มาจากภายในผนัง!",
  ui_story_5082_50821201_51_dialog_content = "โครงสร้างกำลังจะถล่ม! เราต้องเคลียร์สายสัญญาณเหล่านี้และหาที่หลบซ่อน!",
  ui_story_5082_50821201_52_dialog_content = "แต่ PlayerName ล่ะ? ลืมมันไป ฉันจะแบกเขาเอง!",
