  ui_story_5082_50821201_56_dialog_content = "... กระแสไฟฟ้า, การระเบิด, และ... เสียงกรีดร้องของเธอ.",
  ui_story_5082_50821201_57_dialog_content = "ไรน์ฮาร์ต!!!",
  ui_story_5082_50821201_58_dialog_content = "สิ่งเดียวกันก็เกิดขึ้นในตอนนั้น",
  ui_story_5082_50821201_59_dialog_content = "<color=#e8d9bb>กำแพงใกล้เคียงระเบิด ส่งสายสัญญาณและหินตกกระแทกลงสู่พื้น</color>",
  ui_story_5082_50821201_60_dialog_content = "ฟาดฟันไม่หยุด!",
  ui_story_5082_50821201_61_dialog_content = "<color=#e8d9bb>บาร์ตันตัดชิ้นใหญ่ของภาพถ่ายที่กำลังจะตกลงมาครึ่งหนึ่งก่อนที่มันจะตกลงบนเขา</color>",
  ui_story_5082_50821201_62_dialog_content = "<color=#e8d9bb>แล้วเขาก็ยังคงความแรงที่มีอยู่</color>",
  ui_story_5082_50821201_63_dialog_content = "บาร์ตัน...",
  ui_story_5082_50821201_64_dialog_content = "ตอนนี้ไม่ใช่เวลามาฝันกลางวัน! แล้วล่ะ คุณคิดยังไงกับท่าทางของฉันที่เพิ่งแสดงให้เห็น?",
  ui_story_5082_50821201_65_dialog_content = "ฮ่าฮ่าฮ่า มันดุเดือดเหมือนเดิมเลย! ขอบคุณนะครับ คุณบาร์ตัน",
  ui_story_5082_50821201_66_dialog_content = "ขอบคุณที่ต่อสู้เคียงข้างฉันเสมอนะ!",
  ui_story_5082_50821201_67_dialog_content = "มันเป็นธรรมชาติใช่ไหม? มาเถอะ ที่นี่อันตรายเกินไปสำหรับ—",
  ui_story_5082_50821201_68_dialog_content = "ไม่ต้องห่วง, ฉันไม่เป็นไรแล้วนะ",
