  ui_story_5082_50821201_70_dialog_content = "<color=#e8d9bb>ตึกสั่นสะเทือนและพังทลายเมื่อผนังล้มลงมา</color>",
  ui_story_5082_50821201_71_dialog_content = "<color=#e8d9bb>เหมือนกับตาของพายุ ไรน์ฮาร์ตยืนอยู่อย่างไม่เกรงใจในศูนย์กลางของความวุ่นวาย แม้แต่อากาศรอบ ๆ เธอดูเหมือนจะสงบเงียบอย่างสมบูรณ์</color>",
  ui_story_5082_50821201_72_dialog_content = "ไปหาที่กำบัง",
  ui_story_5082_50821201_73_dialog_content = "ฉันยังค้างการแข่งขันใหม่กับหนุ่มคนนี้อยู่",
  ui_story_5082_50821202_1_dialog_content = "ที่นี่คือที่ไหน...?",
  ui_story_5082_50821202_2_dialog_content = "มันเป็นพื้นที่ที่สร้างขึ้นโดยอุปกรณ์นั้น มันใช้ข้อมูลระบบของสเปียร์เฮดเป็นฐานคิด",
  ui_story_5082_50821202_3_dialog_content = "ขอบคุณคุณที่ทำให้สเปียร์เฮดบาดเจ็บจากภายนอก ทำให้เราสามารถหลบภัยได้ปลอดภัยที่นี่",
  ui_story_5082_50821202_4_dialog_content = "พลังของคุณนั้นยอดเยี่ยมมากกว่าที่ฉันเคยคิดไว้",
  ui_story_5082_50821202_5_dialog_content = "ไม่เพียงแค่คุณช่วยฉันควบคุมความรู้สึกของ Spearhead แต่คุณยังสามารถดึงเธอเข้ามาที่นี่ทันทีที่เธอปล่อย Lumina ของเธอ",
  ui_story_5082_50821202_6_dialog_content = "มันแก้ปัญหาการต่อสู้ด้านนอก พร้อมทั้งยังรับรองว่าการทำงานของอุปกรณ์จะไม่ถูกขัดขวาง",
  ui_story_5082_50821202_7_dialog_content = "ฉันแน่ใจว่าคุณจะสามารถทำสิ่งที่น่าทึ่งมากขึ้นด้วยพลังนี้ในอนาคต",
  ui_story_5082_50821202_8_dialog_content = "ขอบคุณ แต่คุณเป็นคนคิดแผนนี้... ซึ่งฉันยังคิดว่ามันอันตรายเกินไป! ถ้าข้อมูลของคุณถูกลบทิ้งล่ะ?!",
  ui_story_5082_50821202_9_dialog_content = "ไม่มีการต่อสู้ที่ไม่มีความเสี่ยงเลย",
