  ui_story_5082_50821202_21_dialog_content = "นั่นคือสิ่งที่ทุกคนเคยเรียกฉันเบื้องหลัง ฉันรู้ว่าพวกเขาไม่ได้หมายความดี แต่ฉันก็ชอบชื่อนั้นเสมอ",
  ui_story_5082_50821202_22_dialog_content = "ฉันแค่ไม่รู้ว่าคุณยังจำเรื่องเหล่านั้นได้หรือไม่ ไรน์ฮาร์ต",
  ui_story_5082_50821202_23_dialog_content = "ฉันเข้าใจแล้ว คุณไม่แน่ใจว่าฉันยังคงเป็นคนเดิมที่คุณเคยรู้จักหรือไม่ และฉันก็เพิ่งจำได้ว่าคุณยังอยู่",
