  ui_story_5082_50821202_30_dialog_content = "เป็นคนของคุณ!",
  ui_story_5082_50821202_31_dialog_content = "คุณคือผู้ที่ทำลายร่างกายของฉัน! คุณคือผู้ที่ฝังฉันให้ยังมีชีวิตอยู่สิบสามปี!",
