  ui_story_5082_50821202_34_dialog_content = "อัก!",
  ui_story_5082_50821202_35_dialog_content = "ฉันสามารถสร้างเขตป้องกันเพื่อขัง Spearhead ไว้ในขณะนี้ แต่นี่ยังคงเป็นอาณาจักรของมัน",
  ui_story_5082_50821202_36_dialog_content = "ด้วยความที่จิตสำนึกของมันยุ่งเหยิงขนาดนี้ ฉันไม่แน่ใจว่าจะสามารถทนต่อไปได้นานแค่ไหน—",
